import { NextRequest, NextResponse } from "next/server";
import { mkdir, rm, writeFile } from "node:fs/promises";
import { dirname } from "node:path";
import { db } from "@/lib/db";
import { getSession } from "@/lib/auth";
import { MAX_REQUEST_DOCUMENT_TOTAL_SIZE } from "@/lib/request-document-constants";
import {
  getRequestDocumentPath,
  prepareRequestDocuments,
  RequestDocumentValidationError,
} from "@/lib/request-document-storage";

// GET /api/transport-requests — role-based filtering
export async function GET(req: NextRequest) {
  const session = await getSession();
  if (!session) return NextResponse.json({ error: "Chưa đăng nhập" }, { status: 401 });

  const { searchParams } = new URL(req.url);
  const status = searchParams.get("status");

  let where: any = {};
  if (status) where.status = status;

  // Role-based filtering
  if (session.roleId === "CUSTOMER") {
    where.customerId = session.userId;
  } else if (session.roleId === "TRANSPORT_SPECIALIST") {
    // Specialist sees submitted + under review + returned (needs their action)
    where.status = { in: ["Đã gửi", "Đang thẩm định", "Trả lại bổ sung"] };
  } else if (session.roleId === "LOGISTICS_MANAGER") {
    // Manager sees reviewed + approved (needs approval action)
    if (!status) where.status = { in: ["Đang thẩm định", "Đã phê duyệt", "Từ chối", "Đã gửi"] };
  }
  // Coordinator and Driver see approved requests (for planning/tracking)

  const requests = await db.transportRequest.findMany({
    where,
    include: {
      customer: true,
      origin: true,
      destination: true,
      horses: { include: { horse: true } },
      approver: true,
    },
    orderBy: { createdAt: "desc" },
  });

  return NextResponse.json({ requests });
}

// POST /api/transport-requests — create (customer only)
export async function POST(req: NextRequest) {
  const session = await getSession();
  if (!session) return NextResponse.json({ error: "Chưa đăng nhập" }, { status: 401 });
  if (session.roleId !== "CUSTOMER") {
    return NextResponse.json({ error: "Chỉ khách hàng mới được tạo yêu cầu" }, { status: 403 });
  }

  let body: any;
  let uploadedFiles: File[] = [];
  if (req.headers.get("content-type")?.includes("multipart/form-data")) {
    const contentLength = Number(req.headers.get("content-length"));
    if (Number.isFinite(contentLength) && contentLength > MAX_REQUEST_DOCUMENT_TOTAL_SIZE + 1024 * 1024) {
      return NextResponse.json({ error: "Tổng dung lượng tài liệu không được vượt quá 50MB." }, { status: 413 });
    }
    const formData = await req.formData();
    const rawHorseIds = formData.get("horseIds");
    let horseIds: unknown = [];
    try {
      horseIds = typeof rawHorseIds === "string" ? JSON.parse(rawHorseIds) : [];
    } catch {
      return NextResponse.json({ error: "Danh sách ngựa không hợp lệ" }, { status: 400 });
    }

    body = {
      horseIds,
      originLocationId: formData.get("originLocationId"),
      destinationLocationId: formData.get("destinationLocationId"),
      competitionName: formData.get("competitionName"),
      scheduledDepartureDate: formData.get("scheduledDepartureDate"),
      scheduledArrivalDate: formData.get("scheduledArrivalDate"),
      deadlineDateTime: formData.get("deadlineDateTime"),
      deadlineTimezone: formData.get("deadlineTimezone"),
      specialRequirements: formData.get("specialRequirements"),
    };
    const documentEntries = formData.getAll("documents");
    if (documentEntries.some((entry) => !(entry instanceof File))) {
      return NextResponse.json({ error: "Danh sách tài liệu không hợp lệ" }, { status: 400 });
    }
    uploadedFiles = documentEntries.filter((entry): entry is File => entry instanceof File);
  } else {
    body = await req.json();
  }

  const { horseIds, originLocationId, destinationLocationId, competitionName,
    scheduledDepartureDate, scheduledArrivalDate, deadlineDateTime, deadlineTimezone, specialRequirements } = body;

  if (!Array.isArray(horseIds) || !horseIds.length || horseIds.some((horseId) => typeof horseId !== "string") ||
    !originLocationId || !destinationLocationId || !scheduledDepartureDate) {
    return NextResponse.json({ error: "Thiếu thông tin bắt buộc" }, { status: 400 });
  }
  if (!deadlineDateTime) {
    return NextResponse.json({ error: "Vui lòng nhập deadline phải có mặt tại điểm đến" }, { status: 400 });
  }
  if (new Set(horseIds).size !== horseIds.length) {
    return NextResponse.json({ error: "Không thể chọn trùng hồ sơ ngựa" }, { status: 400 });
  }

  // Validate horses belong to customer
  const horses = await db.horse.findMany({ where: { horseId: { in: horseIds } } });
  if (horses.length !== horseIds.length) {
    return NextResponse.json({ error: "Không tìm thấy một hoặc nhiều hồ sơ ngựa đã chọn" }, { status: 400 });
  }
  const invalid = horses.some((h) => h.ownerUserId !== session.userId);
  if (invalid) return NextResponse.json({ error: "Ngựa không thuộc tài khoản của bạn" }, { status: 403 });

  let preparedDocuments;
  try {
    preparedDocuments = await prepareRequestDocuments(uploadedFiles);
  } catch (error) {
    if (error instanceof RequestDocumentValidationError) {
      return NextResponse.json({ error: error.message }, { status: 400 });
    }
    throw error;
  }

  const writtenPaths: string[] = [];
  let request;
  try {
    request = await db.$transaction(async (tx) => {
      const createdRequest = await tx.transportRequest.create({
        data: {
          customerId: session.userId,
          originLocationId,
          destinationLocationId,
          competitionName: competitionName || null,
          scheduledDepartureDate: new Date(scheduledDepartureDate),
          scheduledArrivalDate: new Date(scheduledArrivalDate || scheduledDepartureDate),
          deadlineDateTime: deadlineDateTime ? new Date(deadlineDateTime) : null,
          deadlineTimezone: deadlineTimezone || "Asia/Bangkok",
          specialRequirements: specialRequirements || null,
          status: "Nháp",
          currency: "USD",
          horses: { create: horseIds.map((horseId: string) => ({ horseId })) },
        },
        include: {
          horses: { include: { horse: true } },
          origin: true,
          destination: true,
          documents: true,
        },
      });

      for (const document of preparedDocuments) {
        const storagePath = getRequestDocumentPath(createdRequest.requestId, document.documentId);
        writtenPaths.push(storagePath);
        await mkdir(dirname(storagePath), { recursive: true });
        await writeFile(storagePath, document.contents, { flag: "wx" });
        await tx.horseDocument.create({
          data: {
            documentId: document.documentId,
            horseId: horseIds[0],
            requestId: createdRequest.requestId,
            documentType: "Tài liệu yêu cầu",
            fileName: document.fileName,
            fileUrl: `/api/transport-requests/${createdRequest.requestId}/documents/${document.documentId}/file`,
            reviewStatus: "Đã nộp",
          },
        });
      }

      await tx.auditLog.create({
        data: {
          userId: session.userId,
          requestId: createdRequest.requestId,
          action: "Tạo đơn nháp",
          details: `Khách hàng tạo đơn vận chuyển mới${preparedDocuments.length ? ` và đính kèm ${preparedDocuments.length} tài liệu` : ""}.`,
        },
      });
      const requestWithDocuments = await tx.transportRequest.findUnique({
        where: { requestId: createdRequest.requestId },
        include: {
          horses: { include: { horse: true } },
          origin: true,
          destination: true,
          documents: true,
        },
      });
      if (!requestWithDocuments) throw new Error("Created request could not be reloaded.");
      return requestWithDocuments;
    }, { maxWait: 5_000, timeout: 60_000 });
  } catch (error) {
    await Promise.all(writtenPaths.map(async (storagePath) => {
      try {
        await rm(storagePath, { force: true });
      } catch (cleanupError) {
        console.error("Failed to remove an incomplete request document upload.", cleanupError);
      }
    }));
    console.error("Failed to create transport request with its documents.", error);
    return NextResponse.json({ error: "Không thể tạo yêu cầu hoặc lưu tài liệu đính kèm." }, { status: 500 });
  }

  return NextResponse.json({ request }, { status: 201 });
}
